// Loop over input items and add a new field called 'myNewField' to the JSON of each one
let syllabus; 
let source_material;
// console.log($input.all())
for (const item of $input.all()) {
  let content = item["json"];
  if ("data" in content) {
    syllabus = content["data"];
  }
  if ("text" in content) {
    source_material = content["text"]
  }
}
console.log("source material", source_material)
// let merger = {"syllabus": syllabus, "source_material": source_material }
// console.log(merger)
return {"syllabus": syllabus, "source_material": source_material }

